/* CIS*3150 Midterm 2 question bank (lectures 6, 7, 9 and 12: CFGs part 2, PDAs, predictive parsing, parsing tables, Turing machines).
   Prof's format: five choices (a)–(e) in fixed order, shared setups (g), grammars shown as listings.
   Answers checked by computation (FIRST/FOLLOW, LL(1) tables, nullable sets, parse-tree counts, PDA runs).
   ex = class exercise (Oct 27) question as written; exv = a variant in the same style. */
(function () {
  function tbl(head, rows, cls) {
    var h = '<table class="mini ' + (cls || 'ttable') + '"><thead><tr>' + head.map(function (c) { return '<th>' + c + '</th>'; }).join('') + '</tr></thead><tbody>';
    rows.forEach(function (r) { h += '<tr>' + r.map(function (c, i) { return i === 0 ? '<th scope="row">' + c + '</th>' : '<td>' + c + '</td>'; }).join('') + '</tr>'; });
    return h + '</tbody></table>';
  }
  function gram(lines) { return '<pre class="g">' + lines.join('\n') + '</pre>'; }

  window.TOPICS = {
    1: { name: 'CFG design and ambiguity', short: 'CFGs & ambiguity', sections: 'Sipser 2.1, Lecture 6' },
    2: { name: 'Simplifying grammars and CNF', short: 'CNF', sections: 'Sipser 2.1, Lecture 6' },
    3: { name: 'Pushdown automata', short: 'PDAs', sections: 'Sipser 2.2, Lecture 7' },
    4: { name: 'Predictive parsing', short: 'LL(1) parsing', sections: 'Aho 2.4, Lecture 7' },
    5: { name: 'Building parsing tables', short: 'Parse tables', sections: 'Lecture 9' },
    6: { name: 'Turing machines', short: 'Turing machines', sections: 'Sipser 3.1, Lecture 12' }
  };
  // Practice exam: same length and pace as Midterm 1 until the Midterm 2 announcement says otherwise.
  window.EXAM_CONFIG = { n: 29, mix: { 1: 6, 2: 4, 3: 5, 4: 5, 5: 4, 6: 5 } };

  var LLT = tbl(['', 'id', '+', '*', '(', ')', '$'], [
    ['E', 'E → TE′', '', '', 'E → TE′', '', ''],
    ['E′', '', 'E′ → +TE′', '', '', 'E′ → ε', 'E′ → ε'],
    ['T', 'T → FT′', '', '', 'T → FT′', '', ''],
    ['T′', '', 'T′ → ε', 'T′ → *FT′', '', 'T′ → ε', 'T′ → ε'],
    ['F', 'F → id', '', '', 'F → (E)', '', '']], 'ttable lltable');
  var EXPR = gram(['E  → T E′', 'E′ → + T E′ | ε', 'T  → F T′', 'T′ → * F T′ | ε', 'F  → ( E ) | id']);

  window.GROUPS = {
    'g-sip': '<p>Sipser Exercise 2.3. Let G be the grammar below, with start variable R:</p>' + gram(['R → XRX | S', 'S → aTb | bTa', 'T → XTX | X | ε', 'X → a | b']),
    'g-amb': '<p>Consider the grammars G₁ to G₄ from the lecture:</p>' + gram(['G₁:  S → SS | AB     A → Aa | a     B → Bb | b', 'G₂:  S → (L) | a     L → LS | S', 'G₃:  S → AA        A → aA | b', 'G₄:  S → SS | (S) | x | y | z']),
    'g-moreb': '<p>This grammar generates the strings over {a, b} with exactly one more b than a:</p>' + gram(['1. S → bB      2. S → aSS', '3. B → ε       4. B → aS      5. B → bA', '6. A → aB      7. A → bAA']),
    'g-null': '<p>Consider the grammar:</p>' + gram(['S → AACD', 'A → aAb | ε', 'C → aC | a', 'D → aDa | bDb | ε']),
    'g-cnf': '<p>Convert the following grammar to Chomsky normal form:</p>' + gram(['S → ABC | c', 'A → BC | Aa | a', 'B → b', 'C → c']),
    'g-pda': '<p>PDA M₁ from the lecture recognizes {0ⁿ1ⁿ | n ≥ 0}. Q = {q₁, q₂, q₃, q₄}, Σ = {0, 1}, Γ = {0, $}, start q₁, F = {q₁, q₄}. Its transitions (a label “read, pop → push”):</p>' +
      tbl(['From', 'Label', 'To'], [['q₁', 'ε, ε → $', 'q₂'], ['q₂', '0, ε → 0', 'q₂'], ['q₂', '1, 0 → ε', 'q₃'], ['q₃', '1, 0 → ε', 'q₃'], ['q₃', 'ε, $ → ε', 'q₄']]),
    'g-ll': '<p>Consider the expression grammar from the lecture (start symbol E):</p>' + EXPR,
    'g-lltab': '<p>The predictive parser for the expression grammar uses this parsing table (blank = error):</p>' + LLT,
    'g-ll2': '<p>Consider the grammar (start symbol S):</p>' + gram(['S → AB', 'A → aA | ε', 'B → b | c']),
    'g-conf': '<p>Consider the grammar (start symbol S):</p>' + gram(['S → aA | aB', 'A → b', 'B → c']),
    'g-ex4': '<p>Consider the following grammar, from the alphabet {c, *, (, )}:</p>' + gram(['E → E * E | ( E ) | c']),
    'g-zyx': '<p>Consider the grammar from Lecture 9 (start symbol Z; a rule with nothing after ::= derives ε):</p>' + gram(['Z ::= X Y Z  |  d', 'Y ::= c  |  (empty)', 'X ::= a  |  b Y e']),
    'g-rd': '<p>The recursive-descent parser from Lecture 9 has one function per nonterminal (S(), L(), E()) for this grammar:</p>' + gram(['1. S ::= IF E THEN S ELSE S      4. L ::= END', '2. S ::= BEGIN S L                5. L ::= ; S L', '3. S ::= PRINT E                  6. E ::= NUM = NUM']),
    'g-add': '<p>The Lecture 12 Turing machine for f(x, y) = x + y in unary. Input x0y, output (x + y)0; ◊ is the blank; start q₀, accept q₄:</p>' +
      tbl(['From', 'Read → write, move', 'To'], [['q₀', '1 → 1, R', 'q₀'], ['q₀', '0 → 1, R', 'q₁'], ['q₁', '1 → 1, R', 'q₁'], ['q₁', '◊ → ◊, L', 'q₂'], ['q₂', '1 → 0, L', 'q₃'], ['q₃', '1 → 1, L', 'q₃'], ['q₃', '◊ → ◊, R', 'q₄']]),
    'g-dbl': '<p>The Lecture 12 Turing machine for f(x) = 2x in unary. ◊ is the blank; start q₀, accept q₃:</p>' +
      tbl(['From', 'Read → write, move', 'To'], [['q₀', '1 → $, R', 'q₀'], ['q₀', '◊ → ◊, L', 'q₁'], ['q₁', '1 → 1, L', 'q₁'], ['q₁', '$ → 1, R', 'q₂'], ['q₂', '1 → 1, R', 'q₂'], ['q₂', '◊ → 1, L', 'q₁'], ['q₁', '◊ → ◊, R', 'q₃']]),
    'g-tmex': '<p>The Lecture 12 example. Q = {q₀, …, q₄}, Γ = {a, b, x, #}, blank #, Σ = {a, b}, start q₀, F = {q₄}. A label a,R leaves the symbol unchanged:</p>' +
      tbl(['From', 'Label', 'To'], [['q₀', 'a,R', 'q₀'], ['q₀', 'b/x,R', 'q₁'], ['q₀', '#,R', 'q₄'], ['q₁', 'a,R and b,R', 'q₁'], ['q₁', '#,R', 'q₂'], ['q₂', 'a,R and b,R', 'q₂'], ['q₂', '#/b,R', 'q₃'], ['q₃', 'a,L and b,L and #,L', 'q₃'], ['q₃', 'x/#,R', 'q₀']]),
    'g-pal': '<p>The Lecture 12 palindrome detector for strings of 0s and 1s, as 5-tuples (state, read, write, next state, move). ␣ is the blank; A is the start state and Z the accept state:</p>' +
      gram(['(A,1,␣,B,R)  (A,0,␣,C,R)  (A,␣,␣,Z,R)', '(B,0,0,B,R)  (B,1,1,B,R)  (B,␣,␣,D,L)', '(C,0,0,C,R)  (C,1,1,C,R)  (C,␣,␣,E,L)', '(D,1,␣,F,L)  (D,␣,␣,Z,L)', '(E,0,␣,F,L)  (E,␣,␣,Z,L)', '(F,0,0,F,L)  (F,1,1,F,L)  (F,␣,␣,A,R)']),
    'g-comb': '<p>Lecture 12 combines machines: f(x, y) = x + y if x &gt; y, and 0 if x ≤ y. A Comparer sends x, y to an Adder when x &gt; y and to an Eraser (output 0) when x ≤ y.</p>'
  };

  var N5 = ['1', '2', '3', '4', '5'];
  var Q = [
    /* ===================== Topic 1: CFG design and ambiguity ===================== */
    { id: 'c1-01', g: 'g-sip', t: 1, s: 'Sipser 2.3', q: 'What are the variables of G?',
      c: ["{a, b}","{R}","{S, T, X}","{R, S, T, X, a, b}","{R, S, T, X}"], a: 4,
      x: "Variables are the symbols that appear on a left-hand side: R, S, T and X. The terminals are a and b; R alone is the start variable." },
    { id: 'c1-02', g: 'g-sip', t: 1, s: 'Sipser 2.3', q: 'Which statement is true?',
      c: ["T ⇒* T","T ⇒ T","S ⇒* ε","X ⇒* aba","None of the above"], a: 0,
      x: "⇒* allows zero steps, so T ⇒* T always holds. T ⇒ T (exactly one step) is false: every T-rule changes the string. X only yields a or b, and S always produces at least two symbols." },
    { id: 'c1-03', g: 'g-sip', t: 1, s: 'Sipser 2.3', q: 'Which statement is FALSE?',
      c: ["T ⇒* aba","T ⇒* XX","T ⇒* XXX","T ⇒ aba","XXX ⇒* aba"], a: 3,
      x: "One step from T gives XTX, X or ε, never aba, so T ⇒ aba is false. In several steps T ⇒ XTX ⇒ aTa ⇒ aXa ⇒ aba works. T ⇒ XTX ⇒ XX (using T → ε) and T ⇒ XTX ⇒ XXX (using T → X)." },
    { id: 'c1-04', g: 'g-sip', t: 1, s: 'Sipser 2.3', q: 'Which string is in L(G)?',
      c: ["aba","aab","ε","abba","aa"], a: 1,
      x: "R ⇒ S ⇒ aTb ⇒ aXb ⇒ aab. The others are palindromes, and every string in L(G) has a mismatched pair a…b or b…a placed symmetrically." },
    { id: 'c1-05', g: 'g-sip', t: 1, s: 'Sipser 2.3', q: 'Which of the following describes L(G)?',
      c: ["All strings over {a, b} whose length is even","Strings over {a, b} with as many a’s as b’s","All strings over {a, b} that are not palindromes","All palindromes over {a, b}, including the empty string ε","None of the above"], a: 2,
      x: "S → aTb | bTa puts different symbols at mirrored positions, T fills any middle, and R → XRX | S adds any matching-length outer symbols. So w ≠ wᴿ: exactly the non-palindromes." },
    { id: 'c1-06', t: 1, s: 'Designing CFGs', q: 'Which grammar generates {0ⁿ1ⁿ | n ≥ 0} ∪ {1ⁿ0ⁿ | n ≥ 0}?',
      c: ["S → S₁S₂,  S₁ → 0S₁1 | ε,  S₂ → 1S₂0 | ε","S → S₁ | S₂,  S₁ → 0S₁1 | 01,  S₂ → 1S₂0 | 10","S → 0S1 | 1S0 | S₁,  S₁ → 01 | 10 | ε","S → S₁ | S₂,  S₁ → 0S₁1 | ε,  S₂ → 1S₂0 | ε","None of the above"], a: 3,
      x: "A union of languages is S → S₁ | S₂ with a grammar for each part. (a) concatenates them instead; (c) mixes the two patterns and generates 0101; (b) leaves out ε, the case n = 0." },
    { id: 'c1-07', t: 1, s: 'Designing CFGs', q: 'Which grammar generates {aⁿbⁿcᵐdᵐ | n ≥ 1, m ≥ 1}?',
      c: ["S → aSb | cSd | abcd","S → AB,  A → aAb | ε,  B → cBd | ε","S → AB,  A → aAb | ab,  B → cBd | cd","S → aSd | aBd,  B → bBc | bc","None of the above"], a: 2,
      x: "The two halves are independent, so generate each with its own variable and concatenate. (d) is the nested language aⁿbᵐcᵐdⁿ; (b) also allows n = 0 or m = 0; (a) interleaves the parts." },
    { id: 'c1-08', t: 1, s: 'Designing CFGs', q: 'Which grammar generates {aⁿbᵐcᵐdⁿ | n ≥ 1, m ≥ 1}?',
      c: ["S → aSd | aBd,  B → bBc | bc","S → aSd | aBd,  B → bBc | ε","S → AB,  A → aAb | ab,  B → cBd | cd","S → aSd | B,  B → bBc | bc","None of the above"], a: 0,
      x: "The a’s match the d’s on the outside and the b’s match the c’s inside, so generate from the outside in. (d) can skip the a’s entirely (it generates bc); (b) allows m = 0." },
    { id: 'c1-09', t: 1, s: 'Designing CFGs', q: 'Grammar: S → aB | bA,  A → a | aS | bAA,  B → b | bS | aBB. Which string is NOT generated?',
      c: ["aabb","abab","bbaa","baba","aabbb"], a: 4,
      x: "This grammar generates exactly the nonempty strings with equal numbers of a’s and b’s (A produces one extra a, B one extra b). aabbb has three b’s and two a’s." },
    { id: 'c1-10', g: 'g-moreb', t: 1, s: 'Derivations', q: 'Which is a derivation of bab?',
      c: ["S ⇒ aSS ⇒ abBS ⇒ abS ⇒ abbB","S ⇒ bB ⇒ baS ⇒ babB ⇒ bab","S ⇒ bB ⇒ bbA ⇒ bbaB ⇒ bba","S ⇒ bB ⇒ baS ⇒ babA ⇒ bab","None of the above"], a: 1,
      x: "Rules 1, 4, 1, 3: S ⇒ bB ⇒ baS ⇒ babB ⇒ bab. (c) derives bba, not bab; (d) erases A, which has no ε-rule; (a) produces a string starting with a." },
    { id: 'c1-11', g: 'g-moreb', t: 1, s: 'Derivations', q: 'Which string is NOT generated by this grammar?',
      c: ["bba","b","abb","abbab","ab"], a: 4,
      x: "Every generated string has exactly one more b than a. ab has equal counts, so it is not generated." },
    { id: 'c1-12', t: 1, s: 'Ambiguity', q: 'A grammar G is ambiguous if some string in L(G) has',
      c: ["a parse tree of height greater than 2","two derivations of different lengths","two distinct leftmost derivations","both a leftmost and a rightmost derivation","None of the above"], a: 2,
      x: "Ambiguity means two distinct leftmost derivations, equivalently two distinct parse trees. Every derivable string has both a leftmost and a rightmost derivation, so (d) says nothing." },
    { id: 'c1-13', g: 'g-amb', t: 1, s: 'Ambiguity', q: 'Which of the grammars are ambiguous?',
      c: ["G₁ and G₄ only","G₁ only","G₂ and G₃ only","All four","None of them"], a: 0,
      x: "G₁ and G₄ both have S → SS, so three blocks can be grouped two ways (for example ababab in G₁, xyz in G₄). G₂ reads its list left to right inside the parentheses, and in G₃ each A ends at its first b, so their parse trees are forced." },
    { id: 'c1-14', g: 'g-amb', t: 1, s: 'Ambiguity', q: 'Which string shows that G₄ is ambiguous?',
      c: ["x","xyz","((y))","(x)","None of the above"], a: 1,
      x: "xyz = (xy)z or x(yz): S → SS with the left S → SS, or with the right S → SS. Two parse trees. Strings with one symbol have a single tree." },
    { id: 'c1-15', g: 'g-amb', t: 1, s: 'Ambiguity', q: 'Why is G₃ unambiguous?',
      c: ["G₃ generates a finite language, so it is unambiguous","G₃ has no ε-rules, so no grammar like it is ambiguous","A → aA is right recursive, which rules out ambiguity","Each A ends at its first b, so AA splits one way","None of the above"], a: 3,
      x: "A generates a*b, so the first A must end at the first b and the second A is the rest. Having no ε-rules does not prevent ambiguity in general (G₄ has none and is ambiguous), and L(G₃) is infinite." },
    { id: 'c1-16', t: 1, s: 'Ambiguity', q: 'Grammar: S → AS | a | b,  A → SS | ab. Which string has two different parse trees?',
      c: ["ab","b","abb","a","None of the above"], a: 2,
      x: "abb = A S with A → ab and S → b, or A S with A → SS (giving a, b) and S → b. ab is not even in the language: S → AS needs at least three symbols." },
    { id: 'c1-17', t: 1, s: 'Ambiguity', q: 'Grammar: E → E + E | E * E | (E) | x | y | z. How many leftmost derivations does x + y * z have?',
      c: N5, a: 1,
      x: 'Two: one starts E ⇒ E + E (grouping x + (y * z)), the other E ⇒ E * E (grouping (x + y) * z). That is the lecture’s example of ambiguity.' },
    { id: 'c1-18', t: 1, s: 'Ambiguity', q: 'Why is an ambiguous grammar a problem for a compiler?',
      c: ["Two parse trees can give one program two meanings","It generates a language that is not context-free","It cannot be converted to Chomsky normal form","Parsing it with any method never terminates","None of the above"], a: 0,
      x: "The parse tree decides meaning, e.g. whether x + y * z multiplies first. Ambiguous grammars still describe context-free languages and can be put in CNF." },
    { id: 'c1-19', t: 1, s: 'Ambiguity', q: 'The grammar STMT → ASSIGN | IF-THEN | IF-THEN-ELSE, with IF-THEN → if condition then STMT and IF-THEN-ELSE → if condition then STMT else STMT, is ambiguous because',
      c: ["the grammar uses more than one start variable","ASSIGN and IF-THEN both start with a terminal","an if statement can contain another statement","an else can attach to either of two nested ifs","None of the above"], a: 3,
      x: "In “if c then if c then a = 1 else a = 1” the else can belong to the inner or the outer if: the dangling-else problem (Sipser 2.27)." },
    { id: 'c1-20', t: 1, s: 'Ambiguity', q: 'Sipser 2.8: “the girl touches the boy with the flower” has two leftmost derivations. What are the two meanings?',
      c: ["She touches the boy, or the boy touches her with it","The flower touches both of them at the same time","She uses the flower to touch him, or he has the flower","She touches the flower, or she touches the boy with it","None of the above"], a: 2,
      x: "“with the flower” can attach to the verb (the girl touches using the flower) or to the noun phrase (the boy who has the flower). Each attachment is a different parse tree." },

    /* ===================== Topic 2: Simplifying grammars and CNF ===================== */
    { id: 'c2-01', g: 'g-null', t: 2, s: 'Nullable variables', q: 'Which variables are nullable?',
      c: ["∅","{S}","{A, C, D}","{A, D, S}","{A, D}"], a: 4,
      x: "A → ε and D → ε make A and D nullable. C always produces at least one a, so S → AACD is not nullable either." },
    { id: 'c2-02', g: 'g-null', t: 2, s: 'Removing ε-rules', q: 'After eliminating ε-productions (and before removing unit rules), what are the rules for S?',
      c: ["S → AACD | ACD | CD | AAC | AC | ε","S → AACD | ACD | CD | AAC | AC | C","S → AACD | AAD | AD | ACD | CD | D","S → AACD | ACD | AAC | AC | C | ε","None of the above"], a: 1,
      x: "Keep every combination of dropping the nullable A’s and D, but C must stay: AACD, ACD, CD, AAC, AC, C. S is not nullable, so no S → ε." },
    { id: 'c2-03', g: 'g-null', t: 2, s: 'Removing ε-rules', q: 'After eliminating ε-productions, what are the rules for A?',
      c: ["A → ab","A → aAb | a | b","A → aAb | ε","A → aAb | ab","None of the above"], a: 3,
      x: "Drop the ε-rule and add the version of A → aAb with the nullable A removed: ab." },
    { id: 'c2-04', g: 'g-null', t: 2, s: 'Removing ε-rules', q: 'After eliminating ε-productions, what are the rules for D?',
      c: ["D → aDa | bDb | aa | bb","D → aDa | bDb | a | b","D → aDa | bDb | ε","D → aa | bb","None of the above"], a: 0,
      x: "Removing the nullable D from aDa and bDb gives aa and bb. (b) would add odd-length strings that D never produced." },
    { id: 'c2-05', g: 'g-null', t: 2, s: 'Unit rules', q: 'After removing ε-productions, S → C is a unit production. What replaces it?',
      c: ["S → aa","S → C, kept unchanged","S → ε","S → aC | a","None of the above"], a: 3,
      x: "A unit rule S → C is replaced by S → (every right side of C): aC | a." },
    { id: 'c2-06', t: 2, s: 'Nullable variables', q: 'A variable A is nullable when',
      c: ["A ⇒* ε, directly or through nullable variables","A appears on the right side of some ε-rule in G","A has no rules with terminals at all","A is the start variable, which may derive ε","None of the above"], a: 0,
      x: "Lecture definition: A → ε makes A nullable, and A → B₁…Bₙ with every Bᵢ nullable makes A nullable. Nothing else is." },
    { id: 'c2-07', t: 2, s: 'CNF definition', q: 'Which rule is allowed in Chomsky normal form (S is the start variable)?',
      c: ["A → ε","A → BCD","A → B","A → aB","A → BC"], a: 4,
      x: "CNF allows only A → BC (two variables, neither the start variable) and A → a, plus S → ε. aB mixes a terminal with a variable; BCD is too long; A → ε and unit rules are not allowed." },
    { id: 'c2-08', t: 2, s: 'CNF definition', q: 'Which rule is NOT allowed in Chomsky normal form (S is the start variable)?',
      c: ["A → BC","A → a","A → BS","S → ε","None of the above"], a: 2,
      x: "In A → BC, neither B nor C may be the start variable. S → ε is the one ε-rule CNF allows." },
    { id: 'c2-09', t: 2, s: 'CNF conversion', q: 'In the lecture, the steps to convert a grammar to CNF are, in order:',
      c: ["Replace terminals in long rules, split long rules, remove unit rules, remove ε-rules","Remove ε-rules, remove unit rules, replace terminals in long rules, split long rules","Remove unit rules, remove ε-rules, split long rules, replace terminals in long rules","Split long rules, remove ε-rules, remove unit rules, replace terminals in long rules","None of the above"], a: 1,
      x: "ε-rules first (removing them can create unit rules), then unit rules, then make right sides a single terminal or only variables, then cut those down to two variables." },
    { id: 'c2-10', t: 2, s: 'CNF facts', q: 'For a grammar in Chomsky normal form, how many steps does deriving a string of length n ≥ 1 take?',
      c: ['n', '2n', '2n − 1', 'n²', 'n + 1'], a: 2,
      x: 'n − 1 steps of A → BC grow the string to n variables, then n steps of A → a turn each into a terminal: 2n − 1 in total.' },
    { id: 'c2-11', t: 2, s: 'CNF facts', q: 'Which statement about Chomsky normal form is true?',
      c: ["Converting to CNF changes the language slightly","Every context-free language has a grammar in CNF","Only regular languages have grammars in CNF","A grammar in CNF can never generate ε","None of the above"], a: 1,
      x: "Sipser Theorem 2.9: every CFL is generated by a CNF grammar. ε is handled by the single allowed rule S → ε, and the conversion preserves the language." },
    { id: 'c2-12', t: 2, s: 'Unit rules', q: 'A unit production is a rule of the form',
      c: ["A → B, a single variable","A → BC, two variables","A → a, a single terminal","A → ε, the empty string","None of the above"], a: 0,
      x: "A unit rule just renames one variable as another. CNF removes them by copying B’s right sides into A." },
    { id: 'c2-13', g: 'g-cnf', t: 2, s: 'CNF conversion', q: 'Which rule of this grammar is already in CNF?',
      c: ["None of them","A → Aa","S → ABC","A → BC","All of them"], a: 3,
      x: "A → BC has exactly two variables. S → ABC is too long and A → Aa mixes a variable with a terminal. (B → b, C → c, S → c and A → a are also fine.)" },
    { id: 'c2-14', g: 'g-cnf', t: 2, s: 'CNF conversion', q: 'Which is a valid way to convert S → ABC using a new variable D?',
      c: ['S → AD,  D → BC', 'S → DC,  D → AB', 'S → ABD,  D → C', 'S → D,  D → ABC', 'Both (a) and (b) are valid'], a: 4,
      x: 'Either split works: ABC = A(BC) or (AB)C. (c) is still three variables long and (d) adds a unit rule and keeps the long rule.' },
    { id: 'c2-15', g: 'g-cnf', t: 2, s: 'CNF conversion', q: 'How is A → Aa converted?',
      c: ["Replace it with A → a only","Add Xₐ → Aa and use A → Xₐ","Delete it, since it is recursive","Add Xₐ → a and use A → AXₐ","None of the above"], a: 3,
      x: "A terminal inside a longer rule is replaced by a new variable that produces it. A → Xₐ would be a unit rule, and dropping the rule changes the language." },

    /* ===================== Topic 3: Pushdown automata ===================== */
    { id: 'c3-01', g: 'g-pda', t: 3, s: 'Reading PDAs', q: 'Which input does M₁ reject?',
      c: ["ε","0011","01","000111","001"], a: 4,
      x: "001 leaves a 0 on the stack after the only 1 is read, so q₃ never sees $ and M₁ cannot reach q₄. ε is accepted because q₁ itself accepts." },
    { id: 'c3-02', g: 'g-pda', t: 3, s: 'Reading PDAs', q: 'Why is $ pushed before anything else?',
      c: ["To count how many 1s have been read","To make the PDA deterministic","To detect when the stack is empty again","To mark that the input string has ended","None of the above"], a: 2,
      x: "A PDA cannot test for an empty stack directly. Seeing $ on top means every pushed 0 has been matched, so ε, $ → ε can move to the accept state." },
    { id: 'c3-03', g: 'g-pda', t: 3, s: 'Configurations', q: 'While reading 0011, what is on the stack right after the second 0 is read (top first)?',
      c: ["$00","$","0$","00","00$"], a: 4,
      x: "ε, ε → $ first, then each 0 pushes a 0 on top: 00$ with the most recent 0 on top." },
    { id: 'c3-04', g: 'g-pda', t: 3, s: 'Configurations', q: 'Which configuration (state, remaining input, stack) follows (q₂, 11, 00$)?',
      c: ["(q₃, 1, 0$)","(q₃, 11, 0$)","(q₃, 1, 00$)","(q₂, 1, 0$)","None of the above"], a: 0,
      x: "The move 1, 0 → ε reads one 1 and pops one 0, entering q₃: (q₃, 1, 0$)." },
    { id: 'c3-05', g: 'g-pda', t: 3, s: 'Reading PDAs', q: 'Why is q₁ an accept state?',
      c: ["Because every start state must accept","So that ε, the case n = 0, is accepted","So that strings of only 0s are accepted","So that the PDA can reject 1s early","None of the above"], a: 1,
      x: "0⁰1⁰ = ε is in the language, and M₁ can stop in q₁ without moving. Strings of only 0s end in q₂, which does not accept." },
    { id: 'c3-06', t: 3, s: 'Formal definition', q: 'In the PDA M = (Q, Σ, Γ, δ, q₀, F), Γ is',
      c: ["the set of all states","the set of accept states","the transition function","the stack alphabet","the input alphabet"], a: 3,
      x: "Γ (the “tape” alphabet in the lecture) is what can be pushed on the stack. Σ is the input alphabet; it may differ from Γ (M₁ pushes $)." },
    { id: 'c3-07', t: 3, s: 'Formal definition', q: 'The transition function of a PDA has type',
      c: ["δ: Q × Γ_ε → P(Q × Σ_ε)","δ: Q × Σ × Γ → Q × Γ","δ: Q × Σ_ε × Γ_ε → P(Q × Γ_ε)","δ: Q × Σ_ε × Γ_ε → Q × Γ_ε × Σ_ε","None of the above"], a: 2,
      x: "Given a state, an input symbol or ε, and a stack symbol or ε, δ returns a set of (next state, symbol to push) pairs, since a PDA is nondeterministic. (The lecture writes the pair as P(Γ_ε × Q).)" },
    { id: 'c3-08', t: 3, s: 'Formal definition', q: 'On a PDA state diagram, the label a, b → c means',
      c: ["read a, push b, then pop c","read a, pop b, then push c","pop a, read b, then push c","read a and b, then write c","None of the above"], a: 1,
      x: "Read input a, replace b on top of the stack with c. Any of the three may be ε (no read, no pop, no push)." },
    { id: 'c3-09', t: 3, s: 'Power', q: 'Pushdown automata are equivalent in power to',
      c: ["context-free grammars","regular expressions","deterministic finite automata","deterministic PDAs","None of the above"], a: 0,
      x: "A language is context-free exactly when some (nondeterministic) PDA recognizes it. DPDAs are strictly weaker, and DFAs and regular expressions weaker still." },
    { id: 'c3-10', t: 3, s: 'Deterministic PDAs', q: 'Which language is recognized by some PDA but by no deterministic PDA?',
      c: ["{0ⁿ1ⁿ | n ≥ 0}","L(a*b*)","{w | w ends in ab}","{wwᴿ | w ∈ {a, b}*}","None of the above"], a: 3,
      x: "For wwᴿ the machine must guess where the middle is, which needs nondeterminism (lecture slide). 0ⁿ1ⁿ has a DPDA, and the regular languages need no stack at all." },
    { id: 'c3-11', t: 3, s: 'Deterministic PDAs', q: 'A PDA is deterministic when, for every state q and stack symbol Z,',
      c: ["each δ(q, a, Z) has at most one move, and an ε-move rules out input moves","each δ(q, a, Z) has exactly one move, and ε-moves are never allowed","its stack never holds more than one symbol at any point in the computation","it has exactly one accept state, and Γ contains only one stack symbol","None of the above"], a: 0,
      x: "Lecture definition: no δ(q, a, Z) with a ∈ Σ ∪ {ε} has two or more elements, and if δ(q, ε, Z) is nonempty then δ(q, a, Z) is empty for all a ∈ Σ. ε-moves are allowed, just not alongside a competing input move." },
    { id: 'c3-12', t: 3, s: 'Configurations', q: 'An instantaneous description (q, w, γ) of a PDA records',
      c: ["the state, the input already read and the top symbol","the state, the unread input and the stack contents","the current state, a stack symbol and the next move","the start state, the input and the accept states","None of the above"], a: 1,
      x: "q is the current state, w the remaining input and γ the whole stack, top first." },
    { id: 'c3-13', t: 3, s: 'Configurations', q: 'If δ(q, a, Z) contains (p, β), which one-step move is possible?',
      c: ["(q, aw, α) ⊢ (p, w, βZα)","(q, w, Zα) ⊢ (p, aw, βα)","(q, aw, Zα) ⊢ (p, w, βα)","(q, aw, Zα) ⊢ (p, aw, βα)","None of the above"], a: 2,
      x: "The move consumes a from the input and replaces the top symbol Z with β; the rest of the stack α is untouched." },
    { id: 'c3-14', t: 3, s: 'Multi-symbol pushes', q: 'A transition a, s → xyz (push three symbols) is implemented with extra states. Which statement is true?',
      c: ["Each of the three moves reads one more input symbol","All three symbols are pushed by a single ε-move","The PDA must pop s three times, once for each symbol","Only the first move reads input; the rest are ε-moves","None of the above"], a: 3,
      x: "The first move reads a and replaces s with one symbol; ε, ε → … moves through new intermediate states push the others without reading input." },
    { id: 'c3-15', t: 3, s: 'Power', q: 'Which statement about language classes is true?',
      c: ["Regular and context-free mean the same","Every context-free language is regular","Every regular language is context-free","No language is both regular and context-free","None of the above"], a: 2,
      x: "A DFA is a PDA that never uses its stack, so regular ⊂ context-free. {0ⁿ1ⁿ} shows the inclusion is strict." },
    { id: 'c3-16', t: 3, s: 'Designing PDAs', q: 'A PDA for {wwᴿ | w ∈ {a, b}*} works by',
      c: ["pushing w, guessing the middle, then popping to match wᴿ","pushing every symbol and accepting when the stack is full","counting a’s and b’s on the stack and comparing totals","reading the input twice, once forwards and once backwards","None of the above"], a: 0,
      x: "Push symbols, nondeterministically switch at the middle, then pop one symbol per input symbol while they match; accept on reaching $." },

    /* ===================== Topic 4: Predictive (LL(1)) parsing ===================== */
    { id: 'c4-01', g: 'g-ll', t: 4, s: 'FIRST sets', q: 'What is FIRST(E)?',
      c: ["{(, id, ε}","{), $}","{*, ε}","{+, ε}","{(, id}"], a: 4,
      x: "FIRST(E) = FIRST(T) = FIRST(F) = {(, id}. E is not nullable, so ε is not included." },
    { id: 'c4-02', g: 'g-ll', t: 4, s: 'FIRST sets', q: 'What is FIRST(E′)?',
      c: ["{(, id}","{+, ), $}","{+}","{ε}","{+, ε}"], a: 4,
      x: "E′ → +TE′ starts with +, and E′ → ε puts ε in the set." },
    { id: 'c4-03', g: 'g-ll', t: 4, s: 'FOLLOW sets', q: 'What is FOLLOW(E)?',
      c: ["{+, *, ), $}","{(, id}","{+, ), $}","{$}","{), $}"], a: 4,
      x: "$ because E is the start symbol, and ) because of F → ( E )." },
    { id: 'c4-04', g: 'g-ll', t: 4, s: 'FOLLOW sets', q: 'What is FOLLOW(T)?',
      c: ["{+, *, ), $}","{+, ), $}","{+, $}","{), $}","{*, ), $}"], a: 1,
      x: "From E → TE′ and E′ → +TE′: FIRST(E′) − {ε} = {+} follows T, and since E′ is nullable, FOLLOW(E) ∪ FOLLOW(E′) = {), $} is added." },
    { id: 'c4-05', g: 'g-ll', t: 4, s: 'FOLLOW sets', q: 'What is FOLLOW(F)?',
      c: ["{(, id}","{*, ), $}","{+, ), $}","{+, *, (, ), $}","{+, *, ), $}"], a: 4,
      x: "From T → FT′: FIRST(T′) − {ε} = {*}, and since T′ is nullable, FOLLOW(T) = {+, ), $} is added." },
    { id: 'c4-06', g: 'g-lltab', t: 4, s: 'Parsing table', q: 'The entry M[E′, )] is E′ → ε. Why?',
      c: [") is in FIRST(E′) because of F → (E)","E′ is the start symbol of the grammar","every blank entry defaults to an ε-rule",") is in FOLLOW(E′) and E′ can derive ε","None of the above"], a: 3,
      x: "Table rule: if ε ∈ FIRST(α) for A → α, add A → α to M[A, b] for every b ∈ FOLLOW(A). FOLLOW(E′) = {), $}." },
    { id: 'c4-07', g: 'g-lltab', t: 4, s: 'Parsing table', q: 'The top of the stack is T′ and the next input symbol is +. Which production is applied?',
      c: ["E′ → +TE′","T → FT′","T′ → ε","None: this is an error","T′ → *FT′"], a: 2,
      x: "M[T′, +] = T′ → ε: + is in FOLLOW(T′), so T′ disappears and the parser then matches + with E′ → +TE′." },
    { id: 'c4-08', g: 'g-lltab', t: 4, s: 'Parsing table', q: 'The top of the stack is F and the next input symbol is +. What happens?',
      c: ["The parser reports an error","F → (E) is applied","F is popped and + is matched","The parser accepts the input","F → id is applied"], a: 0,
      x: "M[F, +] is blank. No string derived from F can start with +, so the input is rejected." },
    { id: 'c4-09', g: 'g-lltab', t: 4, s: 'Predictive parser', q: 'When the top of the stack is a terminal equal to the current input symbol (not $), the parser',
      c: ["accepts the input string immediately","pops the stack and advances the input","pushes the symbol and advances the input","looks up M[top, input] in the table","None of the above"], a: 1,
      x: "A matching terminal is consumed: pop it and move to the next input symbol. Table lookups happen only for nonterminals on top." },
    { id: 'c4-10', g: 'g-lltab', t: 4, s: 'Predictive parser', q: 'Parsing id + id * id $, the stack starts as E$. After applying E → TE′, T → FT′ and F → id, then matching id, what is the stack (top first)?',
      c: ["E$","E′T′$","T′$","FT′E′$","T′E′$"], a: 4,
      x: "E$ ⇒ TE′$ ⇒ FT′E′$ ⇒ idT′E′$; matching id leaves T′E′$. The next input is +, so T′ → ε is applied next." },
    { id: 'c4-11', t: 4, s: 'Left recursion', q: 'A grammar is (immediately) left recursive if it has a rule of the form',
      c: ["A → a","A → α | β","A → Aα","A → ε","A → αA"], a: 2,
      x: "The variable reappears first on its own right side. A top-down parser for A would call A again before consuming any input." },
    { id: 'c4-12', t: 4, s: 'Left recursion', q: 'Eliminating left recursion from A → Aα | β gives',
      c: ["A → αA′,  A′ → βA′ | ε","A → Aβ | α","A → βA | α","A → βA′,  A′ → αA′ | ε","None of the above"], a: 3,
      x: "A generates βα*, so produce β once and then any number of α’s with a new right-recursive A′." },
    { id: 'c4-13', t: 4, s: 'Left recursion', q: 'Eliminating left recursion from E → E + T | T gives',
      c: ["E → TE′,  E′ → TE′+ | ε","E → TE′,  E′ → +TE′ | ε","E → +TE′,  E′ → T | ε","E → E′T,  E′ → E′+ | ε","None of the above"], a: 1,
      x: "Here α = + T and β = T, so E → TE′ and E′ → +TE′ | ε. (d) is still left recursive in E′." },
    { id: 'c4-14', t: 4, s: 'Left recursion', q: 'Why does a recursive-descent parser fail on E → E + T | T?',
      c: ["E() calls itself before consuming any token, forever","The grammar is ambiguous, so no parser can ever use it","It cannot tell + and T apart without two symbols","T must be parsed before E, which is not possible","None of the above"], a: 0,
      x: "The lecture’s C example: E() immediately calls E() again with the same input, recursing until the stack overflows." },
    { id: 'c4-15', t: 4, s: 'Left factoring', q: 'Left factoring A → αβ₁ | αβ₂ gives',
      c: ["A → β₁A′ | β₂A′,  A′ → α","A → αβ₁,  A′ → αβ₂","A → A′β₁ | A′β₂,  A′ → α","A → αA′,  A′ → β₁ | β₂","None of the above"], a: 3,
      x: "Pull out the common prefix α once and decide between β₁ and β₂ afterwards, when one symbol of lookahead can tell them apart." },
    { id: 'c4-16', t: 4, s: 'Left factoring', q: 'stmt → if expr then stmt else stmt | if expr then stmt is left factored into',
      c: ["stmt → stmt′ else stmt,  stmt′ → if expr then stmt","stmt → if expr then stmt′,  stmt′ → stmt else stmt | ε","stmt → if expr then stmt stmt′,  stmt′ → else stmt | ε","stmt → if expr stmt′,  stmt′ → then stmt | else stmt","None of the above"], a: 2,
      x: "The common prefix “if expr then stmt” is kept once; stmt′ decides whether an else part follows." },
    { id: 'c4-17', t: 4, s: 'LL(1)', q: 'In LL(1), the two L’s and the 1 stand for',
      c: ["left-to-right scan, leftmost derivation, 1 lookahead symbol","leftmost derivation, left recursion, 1 rule per table cell","left-to-right scan, last derivation, 1 stack symbol","left factoring, left recursion, 1 parsing table","None of the above"], a: 0,
      x: "The parser reads input left to right, produces a leftmost derivation, and looks one symbol ahead. LL(k) looks k symbols ahead." },
    { id: 'c4-18', t: 4, s: 'FIRST sets', q: 'FIRST(α) is the set of',
      c: ["productions that can be applied first to α","terminals that can begin a string derived from α","variables that appear first in the rules for α","terminals that can follow α in a sentential form","None of the above"], a: 1,
      x: "Plus ε if α ⇒* ε. (d) is FOLLOW." },
    { id: 'c4-19', t: 4, s: 'FOLLOW sets', q: 'For a nonterminal A, FOLLOW(A) is the set of',
      c: ["rules that are applied after A has been expanded","nonterminals that can appear right after A in some rule","terminals that can appear right after A in a derivation","terminals that can begin a string derived from A","None of the above"], a: 2,
      x: "FOLLOW(A) holds the terminals (and $) that can come immediately after A in some sentential form. (d) is FIRST." },
    { id: 'c4-20', t: 4, s: 'Parsing table', q: 'For a production A → α with ε ∈ FIRST(α), the table also gets A → α in M[A, b] for every b in',
      c: ["FOLLOW(α)","FIRST(A)","FIRST(S)","FOLLOW(A)","None of the above"], a: 3,
      x: "If α can vanish, A → α is right whenever the next symbol is something that can follow A." },
    { id: 'c4-21', t: 4, s: 'FOLLOW sets', q: 'Which rule puts $ into a FOLLOW set?',
      c: ["$ ∈ FOLLOW(S) for the start symbol S","$ ∈ FOLLOW(A) for the last rule listed","$ ∈ FOLLOW(A) when A → ε is a rule","$ ∈ FOLLOW(A) for every nullable A","None of the above"], a: 0,
      x: "FOLLOW rule 1. From there $ spreads to other variables through rule 3 (A → αB puts FOLLOW(A) into FOLLOW(B))." },
    { id: 'c4-22', g: 'g-ll2', t: 4, s: 'FIRST sets', q: 'What is FIRST(S)?',
      c: ["{a}","{a, ε}","{a, b, c, ε}","{b, c}","{a, b, c}"], a: 4,
      x: "S → AB: FIRST(A) − {ε} = {a}, and since A is nullable, FIRST(B) = {b, c} is added. B is not nullable, so ε is not." },
    { id: 'c4-23', g: 'g-ll2', t: 4, s: 'FOLLOW sets', q: 'What is FOLLOW(A)?',
      c: ["{b, c, $}","{b, c}","{a}","{$}","{a, b, c}"], a: 1,
      x: "In S → AB, A is followed by B, so FIRST(B) = {b, c}. B is not nullable, so FOLLOW(S) = {$} does not reach A." },
    { id: 'c4-24', g: 'g-ll2', t: 4, s: 'Parsing table', q: 'What is the table entry M[A, c]?',
      c: ["A → aA","S → AB","B → c","Blank (error)","A → ε"], a: 4,
      x: "c ∈ FOLLOW(A) and A → ε, so M[A, c] = A → ε: on input c the parser lets A vanish and lets B match c." },
    { id: 'c4-25', g: 'g-conf', t: 4, s: 'LL(1) conflicts', q: 'Why is this grammar not LL(1)?',
      c: ["It is left recursive in the variable S","It is ambiguous for the input string ab","M[S, a] would contain two productions","B → c is a unit production","None of the above"], a: 2,
      x: "Both S-rules start with a, so FIRST(aA) and FIRST(aB) overlap and one lookahead symbol cannot choose between them." },
    { id: 'c4-26', g: 'g-conf', t: 4, s: 'Left factoring', q: 'Which left-factored grammar generates the same language and is LL(1)?',
      c: ["S → aS′,  S′ → A | B,  A → b,  B → c","S → Sa | b | c,  A → b,  B → c","S → aA | aB,  A → b | c,  B → c","S → aS′,  S′ → aA | aB,  A → b,  B → c","None of the above"], a: 0,
      x: "Factor out a: S → aS′ and decide between A and B on the next symbol (b or c). (c) still has two S-rules starting with a; (b) is left recursive and generates different strings; (d) needs two a’s." },
    /* Class exercise (Oct 27): questions 2–5 as written, plus variants in the same styles (exv). */
    { id: 'ex-2', ex: 2, g: 'g-sip', t: 1, s: 'Derivations', q: 'True or false: T ⇒ aba',
      c: ["True","False"], a: 1,
      x: "A single arrow ⇒ means exactly one rule application. In one step T can only become XTX, X or ε, so T ⇒ aba is false. In several steps it works (T ⇒ XTX ⇒ aTX ⇒ aXX ⇒ abX ⇒ aba), so T ⇒* aba is true. Check which arrow the question uses." },
    { id: 'ex-2b', exv: 1, g: 'g-sip', t: 1, s: 'Derivations', q: 'True or false: T ⇒* aba',
      c: ["True","False"], a: 0,
      x: "⇒* allows any number of steps: T ⇒ XTX ⇒ aTX ⇒ aXX ⇒ abX ⇒ aba. Compare class exercise Q2, which uses the single arrow ⇒ and is false." },
    { id: 'ex-2c', exv: 1, g: 'g-sip', t: 1, s: 'Derivations', q: 'True or false: R ⇒ S',
      c: ["True","False"], a: 0,
      x: "R → S is one of G’s rules, so R becomes S in exactly one step." },
    { id: 'ex-2d', exv: 1, g: 'g-sip', t: 1, s: 'Derivations', q: 'True or false: S ⇒* aba',
      c: ["True","False"], a: 1,
      x: "Both S-rules put different symbols at the two ends (aTb or bTa). aba starts and ends with a, so S cannot derive it in any number of steps. R ⇒* aba is false too, because aba is a palindrome." },
    { id: 'ex-3', ex: 3, t: 1, s: 'Counting productions', q: 'Consider the following grammar. How many productions are there?' + "<pre class=\"g\">S → AB | c\nA → BS | a\nB → bc | SA</pre>",
      c: ["6","4","5","7","3","None of these"], a: 0,
      x: "Each alternative separated by | is its own production: S → AB, S → c, A → BS, A → a, B → bc and B → SA. The grammar has three lines but six productions. 3 is the number of variables." },
    { id: 'ex-3b', exv: 1, g: 'g-sip', t: 1, s: 'Counting productions', q: 'How many productions does G have?',
      c: ["4","8","9","7","None of these"], a: 2,
      x: "R has 2, S has 2, T has 3 (XTX, X and ε) and X has 2, for 9. T → ε counts as a production; leaving it out gives 8. 4 is the number of variables." },
    { id: 'ex-3c', exv: 1, g: 'g-ll', t: 4, s: 'Counting productions', q: 'How many productions does the expression grammar have?',
      c: ["5","6","10","8","None of these"], a: 3,
      x: "E has 1, E′ has 2, T has 1, T′ has 2 and F has 2, for 8. The ε-rules E′ → ε and T′ → ε count; leaving them out gives 6. 5 is the number of nonterminals." },
    { id: 'ex-4', ex: 4, g: 'g-ex4', t: 1, s: 'Parse trees', q: 'The parse tree for the expression c*(c) will have _____ leaves.',
      c: ["8","7","5","6"], a: 2,
      x: "Read left to right, the leaves of a parse tree spell the string: c, *, (, c, ). That makes 5. The four E nodes are interior nodes, not leaves." },
    { id: 'ex-4b', exv: 1, g: 'g-ex4', t: 1, s: 'Parse trees', q: 'How many nodes labelled E does the parse tree for c*(c) have?',
      c: ["5","4","3","9"], a: 1,
      x: "E → E * E at the root, E → c on the left, E → ( E ) on the right, and E → c inside the brackets: 4 E nodes. 9 is the total number of nodes (4 E nodes plus 5 leaves)." },
    { id: 'ex-4c', exv: 1, g: 'g-ex4', t: 1, s: 'Parse trees', q: 'The string (c)*c*c has two parse trees in this grammar. How many leaves does each tree have?',
      c: ["9 in one tree, 7 in the other","5 in both trees","7 in both trees","9 in both trees"], a: 2,
      x: "The leaves of any parse tree spell the string, so every tree for (c)*c*c has its 7 symbols as leaves. The two trees group the * operations differently, but their leaves are the same." },
    { id: 'ex-5', ex: 5, t: 4, s: 'Left factoring', q: 'Consider the grammar below. Which of the following grammars is obtained by correctly applying left factoring?' + "<pre class=\"g\">statement → IF test THEN statement ELSE statement\nstatement → IF test THEN statement</pre>",
      c: ["statement → IF test A<br>A → THEN statement | ELSE statement","statement → IF test THEN A<br>A → ELSE statement | ε","statement → IF test THEN statement A<br>A → ELSE statement | ε","statement → IF test THEN statement A<br>A → ELSE statement"], a: 2,
      x: "The common prefix is IF test THEN statement, which is the whole of the shorter rule. Factor all of it out and let A choose between ELSE statement and nothing (ε). (a) factors out too little and changes the language; (b) drops the inner statement; (d) has no ε, so every IF would need an ELSE." },
    { id: 'ex-5b', exv: 1, t: 4, s: 'Left factoring', q: 'Which grammar is obtained by correctly left factoring A → abc | abd | e?',
      c: ["A → aA′ | e<br>A′ → bc | bd","A → abA′ | e<br>A′ → c | d","A → abA′<br>A′ → c | d | e","A → abA′ | e<br>A′ → c | d | ε","None of these"], a: 1,
      x: "Take out the longest common prefix, ab, in one step. (a) only takes out a, so both A′ rules still start with b; (c) generates abe instead of e; (d) adds the string ab." },
    { id: 'ex-5c', exv: 1, t: 4, s: 'Left factoring', q: 'The dangling-else grammar in short form is S → iEtS | iEtSeS | a (i = if, t = then, e = else, E = the condition). Which grammar is its correct left factoring?',
      c: ["S → iEtS′ | a<br>S′ → S | SeS","S → iEtSS′ | a<br>S′ → eS","S → iEtSS′<br>S′ → eS | a | ε","S → iEtSS′ | a<br>S′ → eS | ε","None of these"], a: 3,
      x: "The common prefix is iEtS. Factor it out and let S′ choose between eS and ε (the textbook version). (a) leaves S′ with two rules that both start with S; (b) makes every if need an else; (c) removes S → a, so S can never finish and generates nothing." },
    { id: 'ex-5d', exv: 1, t: 4, s: 'Left factoring', q: 'Which grammar is obtained by correctly left factoring E → T + E | T?',
      c: ["E → TE′<br>E′ → +E | ε","E → T + E′<br>E′ → E | ε","E → E′ + E | T<br>E′ → T","E → TE′<br>E′ → +E","None of these"], a: 0,
      x: "The common prefix is T. Factor it out: E → TE′, and E′ chooses between + E (more terms) and ε (done). (b) forces a + after the first T; (c) is still not factored, since both E-rules start with T; (d) has no ε, so E never finishes." },
    /* Topic 5: Lecture 9, building predictive parsing tables. Topic 6: Lecture 12, Turing machines.
       Written in the class-exercise style (exv) ahead of the Nov 3 exercise. Answers checked by computation. */
    { id: 'c5-01', exv: 1, g: 'g-zyx', t: 5, s: 'Nullable', q: 'Which nonterminals are nullable?',
      c: ["X only","Y only","Y and Z","X and Y","None of them"], a: 1,
      x: "Y ::= (empty) makes Y nullable. X always produces a or b…e, and Z needs X or d, so neither can vanish. One round of induction already reaches the fixed point." },
    { id: 'c5-02', exv: 1, g: 'g-zyx', t: 5, s: 'FIRST sets', q: 'What is FIRST(Z)?',
      c: ["{d}","{a, b, c, d}","{a, b}","{a, b, d}","None of these"], a: 3,
      x: "Z ::= d gives d. Z ::= X Y Z starts with X, and X is not nullable, so only FIRST(X) = {a, b} is added. c would only get in if X could vanish." },
    { id: 'c5-03', exv: 1, g: 'g-zyx', t: 5, s: 'FOLLOW sets', q: 'What is FOLLOW(X)?',
      c: ["{a, b, c, d}","{c}","{c, e}","{a, b, c, d, e}","None of these"], a: 0,
      x: "In Z ::= X Y Z, X is followed by Y Z. FIRST(Y) = {c}; Y is nullable, so FIRST(Z) = {a, b, d} is added too. Z is not nullable, so it stops there." },
    { id: 'c5-04', exv: 1, g: 'g-zyx', t: 5, s: 'FOLLOW sets', q: 'What is FOLLOW(Y)?',
      c: ["{c}","{e}","{a, b, d, e}","{a, b, d}","None of these"], a: 2,
      x: "Y is followed by Z in Z ::= X Y Z, giving FIRST(Z) = {a, b, d}, and by e in X ::= b Y e. So FOLLOW(Y) = {a, b, d, e}." },
    { id: 'c5-05', exv: 1, g: 'g-zyx', t: 5, s: 'FOLLOW sets', q: 'Following the lecture slides (no end marker $ is added), what is FOLLOW(Z)?',
      c: ["{a, b, d}","{c}","{e}","{a, b, c, d}","{ } (empty)"], a: 4,
      x: "Z appears only at the right end of its own rule Z ::= X Y Z, which adds FOLLOW(Z) to itself: nothing new. The slides leave it as { }. With the end-marker convention it would be {$}, because Z is the start symbol." },
    { id: 'c5-06', exv: 1, g: 'g-zyx', t: 5, s: 'Parsing table', q: 'What goes in the parsing table at row Y, column d?',
      c: ["Y ::= (empty rule)","Blank (syntax error)","Y ::= c","Z ::= d","None of these"], a: 0,
      x: "The empty rule is nullable and d ∈ FOLLOW(Y), so Y ::= goes in every column of FOLLOW(Y): a, b, d and e. Y ::= c only goes under c." },
    { id: 'c5-07', exv: 1, g: 'g-zyx', t: 5, s: 'Parsing table', q: 'What goes in the parsing table at row Z, column c?',
      c: ["Blank (syntax error)","Z ::= X Y Z","Z ::= d","Y ::= c","None of these"], a: 0,
      x: "c is in neither FIRST(X Y Z) = {a, b} nor FIRST(d), and Z is not nullable, so the cell stays blank. A blank cell means the parser reports a syntax error." },
    { id: 'c5-08', exv: 1, g: 'g-zyx', t: 5, s: 'Parsing table', q: 'With columns a, b, c, d and e, how many cells of the parsing table are filled?',
      c: ["8","9","11","10","None of these"], a: 3,
      x: "Row Z: a and b (Z ::= X Y Z) and d (Z ::= d), 3 cells. Row Y: c (Y ::= c) plus a, b, d and e (the empty rule), 5 cells. Row X: a and b, 2 cells. Total 10, and no cell holds two rules." },
    { id: 'c5-09', exv: 1, g: 'g-zyx', t: 5, s: 'LL(1) conflicts', q: 'The rule Z ::= d e is added to the grammar. What happens to the table?',
      c: ["M[Z, e] gets a second rule, so the grammar is not LL(1)","M[Z, d] gets two rules, so the grammar is not LL(1)","Nothing changes; the table is still conflict-free","Every cell in row Y changes, since FOLLOW(Z) grows","None of these"], a: 1,
      x: "FIRST(d) = FIRST(d e) = {d}, so both rules go in row Z, column d. A cell with two rules means one lookahead symbol cannot choose, so the grammar is not LL(1)." },
    { id: 'c5-10', exv: 1, t: 5, s: 'Left factoring', q: 'Lecture 9 fixes Z ::= X Y Z | d | d e. Which grammar is the correct left factoring of the two d rules?',
      c: ["Z ::= W d,  W ::= ε | e","Z ::= d | W,  W ::= d e","Z ::= d W,  W ::= ε | e","Z ::= d e W,  W ::= d","None of these"], a: 2,
      x: "Take out the common d and let W choose between nothing and e (the slide writes W ::= with an empty right side). (a) puts the choice before d; (b) still has two Z-rules that start with d; (d) generates different strings." },
    { id: 'c5-11', exv: 1, t: 5, s: 'LL(1)', q: 'True or false: a grammar is LL(1) when its predictive parsing table has no cell with two or more rules.',
      c: ["True","False"], a: 0,
      x: "That is the lecture’s definition: no duplicate entries means LL(1) (Left-to-right parse, Leftmost derivation, 1 symbol of lookahead)." },
    { id: 'c5-12', exv: 1, t: 5, s: 'Parsing table', q: 'When is X ::= s entered in row X, column T of the parsing table?',
      c: ["Only when T ∈ FOLLOW(X), whether or not s is nullable","When T ∈ FIRST(X), or X is the start symbol and T is $","When T ∈ FIRST(s), or s is nullable and T ∈ FOLLOW(X)","When T ∈ FOLLOW(s), or T ∈ FIRST(X) and s is nullable","None of these"], a: 2,
      x: "The two rules from the slide: T ∈ FIRST(s) puts X ::= s under T; and if s is nullable, it also goes under every T ∈ FOLLOW(X)." },
    { id: 'c5-13', exv: 1, t: 5, s: 'LL(k)', q: 'In an LL(2) parsing table, the columns are',
      c: ["every sequence of 2 terminals (aa, ab, ba, …)","pairs of nonterminals (XY, YZ, …)","the terminals, plus the end marker $","the terminals that appear twice in the grammar","None of these"], a: 0,
      x: "An LL(k) table has a column for every k-length sequence of terminals, so LL(2) has aa, ab, ba, bb, ac, ca, …" },
    { id: 'c5-14', exv: 1, t: 5, s: 'Fixed point', q: 'Computing nullable, FIRST and FOLLOW in rounds of induction stops when',
      c: ["every set contains at least one terminal","each set has been updated exactly once","the start symbol’s FOLLOW set contains $","a full round changes nothing","None of these"], a: 3,
      x: "Repeat the rules until a whole round adds nothing. On the slides, nullable is fixed after one round, FIRST after two and FOLLOW after two; computing FOLLOW(X) before FOLLOW(Y) would have needed a third round." },
    { id: 'c5-15', exv: 1, g: 'g-rd', t: 5, s: 'Recursive descent', q: 'What does the function L() do when the current token is ;?',
      c: ["eat ;, then call S(), then call L()","eat ;, then call L(), then call S()","call S(), then eat ;","report a syntax error","None of these"], a: 0,
      x: "Rule 5 is L ::= ; S L, so L() eats the ; and then calls the functions for S and L in that order. Each rule’s right side becomes a sequence of eat() calls and function calls." },
    { id: 'c5-16', exv: 1, g: 'g-rd', t: 5, s: 'Recursive descent', q: 'Which token sequence does S() parse without an error?',
      c: ["BEGIN PRINT NUM END","IF NUM = NUM THEN PRINT NUM = NUM","PRINT NUM = NUM ; PRINT NUM = NUM","BEGIN PRINT NUM = NUM END","None of these"], a: 3,
      x: "S ::= BEGIN S L with S ::= PRINT E (E ::= NUM = NUM) and L ::= END. (a) has E as a lone NUM; (b) is missing ELSE S; (c) is two statements, and ; only joins statements inside BEGIN … END." },

    { id: 'c6-01', exv: 1, t: 6, s: 'Definition', q: 'A Turing machine’s transition function δ maps',
      c: ["Q × Σ → Q","Q × Γ → Q × Γ × {L, R}","Q × Σ_ε × Γ_ε → P(Q × Γ_ε)","Q × Γ → Γ × {L, R}","None of these"], a: 1,
      x: "From the current state and tape symbol, δ gives the next state, the symbol to write and the direction to move. (a) is a DFA, (c) is a PDA, and (d) forgets the next state." },
    { id: 'c6-02', exv: 1, t: 6, s: 'Transitions', q: 'On a Turing machine diagram, the edge label a/b,R means',
      c: ["read a, write b, move right","read a, push b, move right","read b, write a, move right","write a, read b, move right","None of these"], a: 0,
      x: "δ(qᵢ, a) = (qⱼ, b, R): replace the current symbol a by b and move one cell right." },
    { id: 'c6-03', exv: 1, t: 6, s: 'Transitions', q: 'An edge labelled just “b,L” means',
      c: ["read b, erase it, move left","read b, leave it, move left","read anything, write b, move left","read b, then halt after moving left","None of these"], a: 1,
      x: "When the symbol written equals the symbol read, the slides write “b,L” instead of “b/b,L”." },
    { id: 'c6-04', exv: 1, t: 6, s: 'Definition', q: 'In the tuple (Q, Σ, Γ, δ, q₀, F), which is true?',
      c: ["Γ ⊆ Σ","blank ∈ Σ","F ⊆ Γ","Σ ⊆ Γ − {blank}","None of these"], a: 3,
      x: "The input alphabet is part of the tape alphabet and never contains the blank. F ⊆ Q (states, not symbols)." },
    { id: 'c6-05', exv: 1, t: 6, s: 'Acceptance', q: 'L(M), the language accepted by a Turing machine M, is the set of input strings that cause M to',
      c: ["halt in a final state","read every symbol of the input","halt, in any state","erase its whole tape","None of these"], a: 0,
      x: "M starts in q₀ with the head on the leftmost input cell, and accepts if it halts in a final state." },
    { id: 'c6-06', exv: 1, t: 6, s: 'Acceptance', q: 'True or false: if a Turing machine does not accept an input, it must halt in a non-final state.',
      c: ["True","False"], a: 1,
      x: "If an input is not accepted, the machine may never halt at all. That possibility is what leads to undecidable problems." },
    { id: 'c6-07', exv: 1, t: 6, s: 'Mechanical procedure', q: 'Which is NOT part of Turing’s idea of a mechanical procedure?',
      c: ["A finite number of instructions","Input that is not restricted in size","Output of unlimited size","Unlimited storage space","Infinitely many internal states"], a: 4,
      x: "The procedure has a finite number of internal states; the unlimited part is the tape (input, storage and output)." },
    { id: 'c6-08', exv: 1, t: 6, s: 'Unary', q: 'In unary, the number 4 is written as',
      c: ["100","0000","1111","11110","None of these"], a: 2,
      x: "Unary uses one 1 per unit. The slides prefer it because it is easier for a Turing machine to manipulate (5 = 11111, binary 101)." },
    { id: 'c6-09', exv: 1, g: 'g-add', t: 6, s: 'Adder', q: 'What is the input tape for f(3, 2)?',
      c: ["11011","111011","1110110","11111","None of these"], a: 1,
      x: "The input is x0y in unary: 111, the delimiter 0, then 11." },
    { id: 'c6-10', exv: 1, g: 'g-add', t: 6, s: 'Adder', q: 'What is on the tape when the machine halts on input 111011?',
      c: ["11111","111101","1111100","111110","None of these"], a: 3,
      x: "The output format is (x + y)0: five 1s, then the 0. The machine turns the delimiter into a 1, then turns the last 1 into a 0." },
    { id: 'c6-11', exv: 1, g: 'g-add', t: 6, s: 'Adder', q: 'Starting from 11011 at time 0, after how many moves does the machine halt in q₄?',
      c: ["10","11","12","13","None of these"], a: 2,
      x: "As on the slides: 5 moves right to the blank (times 1–5), 1 move left into q₂, 1 move writing the 0, 4 moves left through the 1s to the blank, and 1 move right into q₄: halted at time 12." },
    { id: 'c6-12', exv: 1, g: 'g-add', t: 6, s: 'Adder', q: 'What is the job of the move q₂: 1 → 0, L?',
      c: ["It undoes the extra 1 created when the delimiter became a 1","It marks where x ends so that q₃ can stop in the right place","It erases the 0 delimiter so that x and y join into one block","It checks that y is not empty before the machine returns left","None of these"], a: 0,
      x: "q₀ wrote a 1 over the delimiter, so there is one 1 too many. q₂ changes the last 1 into the 0 that ends the output (x + y)0." },
    { id: 'c6-13', exv: 1, g: 'g-dbl', t: 6, s: 'Doubler', q: 'What does the machine leave on the tape for input 111?',
      c: ["111","11111","$$$111","111111","None of these"], a: 3,
      x: "f(x) = 2x in unary: three 1s become six." },
    { id: 'c6-14', exv: 1, g: 'g-dbl', t: 6, s: 'Doubler', q: 'What is the $ used for?',
      c: ["It marks the right end of the input","It separates x from its copy","It is the machine’s blank symbol","It marks a 1 not yet copied","None of these"], a: 3,
      x: "First every 1 becomes $. Then, repeatedly, the rightmost $ is turned back into 1 and a new 1 is added at the right end, until no $ remains." },
    { id: 'c6-15', exv: 1, g: 'g-tmex', t: 6, s: 'Tracing', q: 'What is on the tape when the machine halts on baabab###…?',
      c: ["baabab#bbb","xaaxax#bbb","aaa#bbb","#aa#a##bbb","None of these"], a: 3,
      x: "Each b is first marked x, a b is written after the blank that ends the input, and then the x becomes #. The a’s stay where they were. Checked by simulation: it halts in q₄ after 45 moves." },
    { id: 'c6-16', exv: 1, g: 'g-tmex', t: 6, s: 'Tracing', q: 'In general, what does this machine do?',
      c: ["Accepts only the strings with equal numbers of a’s and b’s","Copies each b past the end and blanks out the original","Copies the whole input to after a blank, leaving the original","Erases every a and moves the b’s together at the left end","None of these"], a: 1,
      x: "q₀ skips a’s; on a b it writes x, runs right past the end (q₁, q₂), writes a b, comes back (q₃) and turns the x into #. When q₀ reaches the blank after the input, it accepts." },
    { id: 'c6-17', exv: 1, t: 6, s: 'Encoding', q: 'In the lecture’s 5-tuple encoding, (A, 1, x, B, R) means',
      c: ["in state A reading 1: write x, move right, go to B","in state A reading x: write 1, move right, go to B","in state B reading 1: write x, move right, go to A","in state A reading 1: move right to B, then write x","None of these"], a: 0,
      x: "(current state, symbol read, symbol written, next state, direction): δ(A, 1) = (B, x, R)." },
    { id: 'c6-18', exv: 1, g: 'g-pal', t: 6, s: 'Palindromes', q: 'Which input does the palindrome detector accept?',
      c: ["0100","10","001","1001","None of these"], a: 3,
      x: "It erases the first symbol, remembers it in state B (1) or C (0), checks and erases a matching last symbol (D or E), returns (F) and repeats. 1001 empties out and reaches Z; 0100, 10 and 001 each find a mismatch and halt in a non-accepting state." },
    { id: 'c6-19', exv: 1, g: 'g-pal', t: 6, s: 'Palindromes', q: 'What does being in state B tell the machine?',
      c: ["The string has odd length so far","The last symbol read was a 1","The first symbol was 1 (now erased)","A 0 must be found at the right end","None of these"], a: 2,
      x: "(A, 1, ␣, B, R): the machine erases a leading 1 and uses state B to remember it, so that D can check the last symbol is also 1." },
    { id: 'c6-20', exv: 1, g: 'g-comb', t: 6, s: 'Combining machines', q: 'Using the block diagram, what is f(3, 3)?',
      c: ["6","3","1","0","None of these"], a: 3,
      x: "3 > 3 is false, so the Comparer sends x, y to the Eraser, which outputs 0. Only when x > y does the Adder run." },
    { id: 'c6-21', exv: 1, t: 6, s: 'Comparer', q: 'For f(x, y) = 1 if x > y and 0 if x ≤ y, what is the input tape for x = 2, y = 3?',
      c: ["11111","110111","1100111","23","None of these"], a: 1,
      x: "Input x0y in unary: 11, the delimiter 0, then 111. The machine matches 1s from x and y; x runs out first, so it erases the tape and writes 0." },
    { id: 'c6-22', exv: 1, t: 6, s: 'History', q: 'Which pairing is correct?',
      c: ["Gödel, 1931: the Turing machine as a model of computation","Turing, 1936: the Turing machine as a model of computation","Hilbert, 1931: the incompleteness theorem","Turing, 1931: the incompleteness theorem","None of these"], a: 1,
      x: "Hilbert asked for an algorithm deciding every mathematical proposition; Gödel’s incompleteness theorem (1931) showed some questions cannot be answered yes or no; Turing proposed his machine in 1936." },
    { id: 'c6-23', exv: 1, t: 6, s: 'TM vs PDA', q: 'What can a Turing machine do that a PDA cannot?',
      c: ["Keep a finite number of states in its control","Read its input symbols from left to right","Move its head both ways and write on the tape","Make nondeterministic choices between moves","None of these"], a: 2,
      x: "The tape is input, storage and output at once, and the head can move left or right and overwrite cells. A PDA reads its input once, left to right, and can only use its stack." }
  ];

  Q.forEach(function (q) { q.fmt = 'prof'; q.keep = true; });
  window.QB = Q;
})();
